478	export const recordProcessor: Processor<schemas.$ZodRecord> = (schema, ctx, _json, params) => {
479	  const json = _json as JSONSchema.ObjectSchema;
480	  const def = schema._zod.def as schemas.$ZodRecordDef;
481	  json.type = "object";
482	
483	  // For looseRecord with regex patterns, use patternProperties. This correctly represents "only validate keys matching the pattern" semantics and composes well with allOf (intersections)
484	  const keyType = def.keyType as schemas.$ZodTypes;
485	  const keyBag = keyType._zod.bag as schemas.$ZodStringInternals<unknown>["bag"] | undefined;
486	  const patterns = keyBag?.patterns;
487	
488	  if (def.mode === "loose" && patterns && patterns.size > 0) {
489	    // Use patternProperties for looseRecord with regex patterns
490	    const valueSchema = process(def.valueType, ctx as any, {
491	      ...params,
492	      path: [...params.path, "patternProperties", "*"],
493	    });
494	    json.patternProperties = {};
495	    for (const pattern of patterns) {
496	      assignProp(json.patternProperties, pattern.source, valueSchema);
497	    }
498	  } else {
499	    // Default behavior: use propertyNames + additionalProperties
500	    if (ctx.target === "draft-07" || ctx.target === "draft-2020-12") {
501	      json.propertyNames = process(def.keyType, ctx as any, {
502	        ...params,
503	        path: [...params.path, "propertyNames"],
504	      });
505	    }
506	    json.additionalProperties = process(def.valueType, ctx as any, {
507	      ...params,
508	      path: [...params.path, "additionalProperties"],
509	    });
510	  }
511	
512	  // Add required for keys with discrete values (enum, literal, etc.)
513	  const keyValues = keyType._zod.values;
514	  // Every key shares one value schema, so an optional-in value makes the whole key set omittable on input. Output keeps them: the exhaustive branch assigns every key, even one whose value came back undefined.
515	  const omittableOnInput = ctx.io === "input" && inputOptin(def.valueType as schemas.$ZodType) !== undefined;
516	  if (keyValues && !def.partial && !omittableOnInput) {
517	    const validKeyValues = [...keyValues].filter(
518	      (v): v is string | number => typeof v === "string" || typeof v === "number"
519	    );
520	
521	    if (validKeyValues.length > 0) {
522	      json.required = validKeyValues as string[];
523	    }
524	  }
525	};
