527	export const nullableProcessor: Processor<schemas.$ZodNullable> = (schema, ctx, json, params) => {
528	  const def = schema._zod.def as schemas.$ZodNullableDef;
529	  const inner = process(def.innerType, ctx as any, params);
530	  const seen = ctx.seen.get(schema)!;
531	  if (ctx.target === "openapi-3.0") {
532	    seen.ref = def.innerType;
533	    json.nullable = true;
534	  } else {
535	    json.anyOf = [inner, { type: "null" }];
536	  }
537	};
