209	export function process<T extends schemas.$ZodType>(
210	  schema: T,
211	  ctx: ToJSONSchemaContext,
212	  _params: ProcessParams = { path: [], schemaPath: [] }
213	): JSONSchema.BaseSchema {
214	  const def = schema._zod.def as schemas.$ZodTypes["_zod"]["def"];
215	
216	  // check for schema in seens
217	  const seen = ctx.seen.get(schema);
218	
219	  if (seen) {
220	    seen.count++;
221	
222	    // check if cycle
223	    const isCycle = _params.schemaPath.includes(schema);
224	    if (isCycle) {
225	      seen.cycle = _params.path;
226	    }
227	
228	    return seen.schema;
229	  }
230	
231	  // initialize
232	  const result: Seen = { schema: {}, count: 1, cycle: undefined, path: _params.path };
233	  ctx.seen.set(schema, result);
234	  ctx.sharedDefsExtractedFor = undefined;
235	  ctx.sharedEmitDoneFor = undefined;
236	
237	  // custom method overrides default behavior
238	  const overrideSchema = schema._zod.toJSONSchema?.();
239	  if (overrideSchema) {
240	    result.schema = overrideSchema as any;
241	  } else {
242	    const params = {
243	      ..._params,
244	      schemaPath: [..._params.schemaPath, schema],
245	      path: _params.path,
246	    };
247	
248	    if (schema._zod.processJSONSchema) {
249	      schema._zod.processJSONSchema(ctx, result.schema, params);
250	    } else {
251	      const _json = result.schema;
252	      const processor = ctx.processors[def.type];
253	      if (!processor) {
254	        throw new Error(`[toJSONSchema]: Non-representable type encountered: ${def.type}`);
255	      }
256	      processor(schema, ctx, _json, params);
257	    }
258	
259	    const parent = schema._zod.parent as T;
260	
261	    if (parent) {
262	      // Also set ref if processor didn't (for inheritance)
263	      if (!result.ref) result.ref = parent;
264	      process(parent, ctx, params);
265	      ctx.seen.get(parent)!.isParent = true;
266	    }
267	  }
268	
269	  // metadata
270	  const meta = ctx.metadataRegistry.get(schema);
271	  if (meta) assignProps(result.schema, meta);
272	
273	  if (ctx.io === "input" && isTransforming(schema)) {
274	    // examples/defaults only apply to output type of pipe
275	    delete result.schema.examples;
276	    delete result.schema.default;
277	  }
278	
279	  // set prefault as default
280	  if (ctx.io === "input" && "_prefault" in result.schema) result.schema.default ??= result.schema._prefault;
281	  delete result.schema._prefault;
282	
283	  // pulling fresh from ctx.seen in case it was overwritten
284	  const _result = ctx.seen.get(schema)!;
285	
286	  return _result.schema;
287	}
